use std::{fs,path::Path,collections::{BTreeMap,BTreeSet},process::Command};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-poseidon-parallel";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn median(mut v:Vec<f64>)->f64{assert!(!v.is_empty());v.sort_by(f64::total_cmp);if v.len()%2==1{v[v.len()/2]}else{(v[v.len()/2-1]+v[v.len()/2])/2.}}
fn gm(v:&[f64])->f64{assert!(!v.is_empty()&&v.iter().all(|x|*x>0.&&x.is_finite()));(v.iter().map(|x|x.ln()).sum::<f64>()/v.len()as f64).exp()}
fn paired(v:&[f64],base:&[f64])->Value{let ratios:Vec<_>=v.iter().zip(base).map(|(v,b)|v/b).collect();assert_eq!(ratios.len(),7);json!({"geometric_ratio":gm(&ratios),"median_ratio":median(ratios.clone()),"wins":ratios.iter().filter(|x|**x<1.).count(),"block_ratios":ratios})}
fn values(rows:&[Value],case:&str,mode:&str,key:&str)->Vec<f64>{(0..7).map(|block|rows.iter().find(|x|x["phase"]=="latency"&&x["case"]==case&&x["stage"]["block"]==block&&x["stage"]["mode"]==mode).unwrap()["stage"][key].as_f64().unwrap()).collect()}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("measure/result.json"))["status"],"complete");let pins=read(r.join("measurement-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}
 let mut rows=Vec::new();let mut affinity=BTreeMap::new();let mut profile_stages=BTreeMap::new();let mut sorts=0;let mut allocs=0;let mut maxrss=0;for job in read(r.join("jobs.json")).as_array().unwrap(){let name=job["name"].as_str().unwrap();let log=fs::read_to_string(r.join("measure").join(name).join("stdout.log")).unwrap();let receipt:Value=serde_json::from_str(log.lines().find_map(|l|l.strip_prefix("AFFINITY ")).unwrap()).unwrap();assert_eq!(receipt["before"],receipt["after"]);let workers=if job["phase"]=="latency"{job["case"]["workers"].as_u64().unwrap()}else{32};assert_eq!(receipt["before"].as_array().unwrap().len(),workers as usize);for(i,w)in receipt["before"].as_array().unwrap().iter().enumerate(){assert_eq!(w["worker"],i);assert_eq!(w["allowed"],json!([i]));assert_eq!(w["cpu"],i);}
 let stages:Vec<Value>=log.lines().filter_map(|l|l.strip_prefix("STAGE ")).map(|s|serde_json::from_str(s).unwrap()).collect();assert_eq!(stages.len(),if job["phase"]=="latency"{28}else{1});let mut seen=BTreeSet::new();for s in stages{assert_eq!(s["all_outputs_match_interpreter"],true);assert_eq!(s["workers"],workers);assert_eq!(s["iterations"],if job["phase"]=="latency"{job["case"]["iterations"].clone()}else{json!(4096)});assert!(seen.insert((s["block"].as_u64().unwrap(),s["mode"].as_str().unwrap().to_string())));sorts+=s["sort_allocation_calls"].as_u64().unwrap();allocs+=s["timed_allocation_calls"].as_u64().unwrap();maxrss=maxrss.max(s["whole_process_maxrss_kib"].as_u64().unwrap());assert_eq!(s["grouping_enabled"],s["mode"]=="grouped"&&s["groups"]==16);
 if job["phase"]=="profile"{assert_eq!(s["mode"],job["mode"]);profile_stages.insert(job["mode"].as_str().unwrap().to_string(),s.clone());}rows.push(json!({"phase":job["phase"],"case":name,"stage":s}));}affinity.insert(name.to_string(),receipt);}
 assert_eq!(rows.len(),676);let mut cases=BTreeMap::new();let mut calibration=Vec::new();let mut failures=Vec::new();let mut affected:BTreeMap<&str,Vec<Vec<f64>>>=[("control-a",vec![vec![];7]),("control-b",vec![vec![];7])].into_iter().collect();let mut ragged_plain=vec![vec![];7];
 for case in read(r.join("cases.json")).as_array().unwrap(){let name=case["name"].as_str().unwrap();let a=values(&rows,name,"control-a","ns_per_epoch");let b=values(&rows,name,"control-b","ns_per_epoch");let p=values(&rows,name,"plain","ns_per_epoch");let g=values(&rows,name,"grouped","ns_per_epoch");let cal=paired(&b,&a);let med=cal["median_ratio"].as_f64().unwrap();let geo=cal["geometric_ratio"].as_f64().unwrap();if !(1./1.03..=1.03).contains(&med){calibration.push(format!("{name}:median B/A={med}"));}if !(1./1.05..=1.05).contains(&geo){calibration.push(format!("{name}:geometric B/A={geo}"));}
 let mut pairs=BTreeMap::new();for(control,base)in [("control-a",&a),("control-b",&b),("plain",&p)]{let pair=paired(&g,base);let ratio=pair["geometric_ratio"].as_f64().unwrap();let wins=pair["wins"].as_u64().unwrap();if control!="plain"{if ratio>1.02{failures.push(format!("{name}:grouped/{control}={ratio}>1.02"));}if case["groups"]==16{if ratio>=1.||wins<4{failures.push(format!("{name}:affected grouped/{control}={ratio},wins{wins}/7"));}for(block,x)in pair["block_ratios"].as_array().unwrap().iter().enumerate(){affected.get_mut(control).unwrap()[block].push(x.as_f64().unwrap());}}}else if case["groups"]==16&&case["ragged"]==true{for(block,x)in pair["block_ratios"].as_array().unwrap().iter().enumerate(){ragged_plain[block].push(x.as_f64().unwrap());}}pairs.insert(control,pair);}
 let mut resources=BTreeMap::new();for mode in ["control-a","control-b","plain","grouped"]{let mut obj=serde_json::Map::new();for key in ["ns_per_epoch","user_cpu_ms","system_cpu_ms","voluntary_switches","involuntary_switches","minor_faults","sort_ms","whole_process_maxrss_kib"]{obj.insert(key.into(),json!(median(values(&rows,name,mode,key))));}resources.insert(mode,Value::Object(obj));}
 cases.insert(name.to_string(),json!({"case":case,"control_a_us_per_epoch":median(a)/1000.,"control_b_us_per_epoch":median(b)/1000.,"plain_us_per_epoch":median(p)/1000.,"grouped_us_per_epoch":median(g)/1000.,"calibration":cal,"pairs":pairs,"resource_medians":resources}));}
 let mut aggregates=BTreeMap::new();for(control,blocks)in affected{let ratios:Vec<_>=blocks.iter().map(|v|{assert_eq!(v.len(),8);gm(v)}).collect();let ratio=gm(&ratios);let wins=ratios.iter().filter(|x|**x<1.).count();if ratio>=1.||wins<4{failures.push(format!("affected aggregate grouped/{control}={ratio},wins{wins}/7"));}aggregates.insert(control,json!({"geometric_ratio":ratio,"wins":wins,"block_ratios":ratios}));}
 let rp:Vec<_>=ragged_plain.iter().map(|v|{assert_eq!(v.len(),4);gm(v)}).collect();let rpg=gm(&rp);let rpw=rp.iter().filter(|x|**x<1.).count();if rpg>=1.||rpw<4{failures.push(format!("affected ragged aggregate grouped/plain={rpg},wins{rpw}/7"));}aggregates.insert("ragged-plain",json!({"geometric_ratio":rpg,"wins":rpw,"block_ratios":rp}));
 let mut profiles=BTreeMap::new();let mut raw=BTreeMap::new();for mode in ["control-a","control-b","plain","grouped"]{let text=fs::read_to_string(r.join(format!("measure/samples-{mode}/stdout.log"))).unwrap();assert!(!text.contains("PERF_RECORD_LOST")&&!text.lines().any(|l|l.split_whitespace().any(|w|w=="LOST")));let receipt=&affinity[&format!("profile-{mode}")];let allowed:BTreeSet<_>=receipt["before"].as_array().unwrap().iter().map(|w|w["tid"].as_u64().unwrap()).collect();let mut pids=BTreeSet::new();let mut tids=BTreeSet::new();let mut symbols:BTreeMap<String,(usize,u64)>=BTreeMap::new();let mut categories:BTreeMap<&str,u64>=BTreeMap::new();let mut period=0u64;let mut samples=0;
 for line in text.lines(){let f:Vec<_>=line.split_whitespace().collect();if f.len()<7||f[4]!="cycles:u:"{continue;}let(pid,tid)=f[1].split_once('/').unwrap();let pid:u64=pid.parse().unwrap();let tid:u64=tid.parse().unwrap();assert!(allowed.contains(&tid)||tid==pid);pids.insert(pid);tids.insert(tid);let n:u64=f[3].parse().unwrap();assert!(n>0);period=period.checked_add(n).unwrap();samples+=1;let sym=f[6];let e=symbols.entry(sym.into()).or_default();e.0+=1;e.1+=n;let category=if sym.contains("7across8"){"across8"}else if sym.contains("13emit_poseidon")||sym.contains("12run_poseidon"){"old_scalar_poseidon"}else if sym.contains("10rayon_core"){"rayon_core"}else{"other"};*categories.entry(category).or_default()+=n;
 }assert!(samples>0);assert_eq!(pids.len(),1);assert!(tids.len()<=33);let mut list:Vec<_>=symbols.into_iter().map(|(sym,(count,p))|json!({"symbol":sym,"samples":count,"period":p,"percent":100.*p as f64/period as f64})).collect();list.sort_by(|a,b|b["period"].as_u64().cmp(&a["period"].as_u64()));let cats:BTreeMap<_,_>=categories.into_iter().map(|(k,p)|(k,json!({"period":p,"percent":100.*p as f64/period as f64}))).collect();profiles.insert(mode,json!({"stage":profile_stages[mode],"samples":samples,"period":period,"pids":pids,"tids":tids,"lost_records":0,"categories":cats,"symbols":list}));
 let data=r.join(format!("profiles/{mode}/perf.data"));let out=Command::new("sudo").args(["-n","sha256sum"]).arg(&data).output().unwrap();assert!(out.status.success());raw.insert(data.display().to_string(),String::from_utf8(out.stdout).unwrap().split_whitespace().next().unwrap().to_string());}
 let a=json!({"cases":cases,"affected_aggregates":aggregates,"calibration_failures":calibration,"speed_or_nonregression_failures":failures,"component_advances":calibration.is_empty()&&failures.is_empty(),"profiles":profiles,"latency_processes":24,"latency_stages":672,"profile_processes":4,"all676_stages_outputs_match_interpreter":true,"sorting_allocation_calls":sorts,"timed_allocation_calls":allocs,"whole_process_maxrss_kib":maxrss,"SDK_requests":0,"Gnark_exports":0,"next_prior_count":6946,"adopted":false,"goal_achieved":false});save(r.join("rows.json"),&json!(rows));save(r.join("affinity.json"),&json!(affinity));save(r.join("analysis.json"),&a);save(r.join("raw-local-only-sha256.json"),&json!(raw));println!("{}",serde_json::to_string_pretty(&json!({"advances":a["component_advances"],"affected":a["affected_aggregates"],"calibration":a["calibration_failures"],"failures":a["speed_or_nonregression_failures"],"allocation_calls":a["timed_allocation_calls"]})).unwrap());
}
